sharedSurface.types:
src/types.ts additions (exact):

// Project
dbServices?: Array<{ id: string; name: string; createdAt: number; templateDeploymentId?: string }>       // id = `pg-${name}`; order = creation order; the oldest gets the canonical DATABASE_URL alias
storageServices?: Array<{ id: string; name: string; createdAt: number; public?: boolean }>               // id = `st-${name}`; `public` = project-level default applied to new branches
computeServices?: Record<string, { createdAt?: number; alwaysOn?: boolean; port?: number; templateDeploymentId?: string; templateCode?: string; templateModified?: boolean }>  // keyed by group; computeGroups stays the registration list (compat)

// Branch
databases?: Record<string, { url: string; container: string }>                     // keyed by service id (pg-<name>); container = `io-${ref}-pg-${name}` (legacy row: `io-${ref}-pg`)
buckets?: Record<string, { bucket: string; env: Record<string, string>; public?: boolean }>   // keyed by st-<name>; bucket = `io-${ref}-${name}` (legacy row: `io-${ref}`)
bindings?: Array<{ envName: string; target: string; source: string; sourceName: string }>   // target 'compute/<group>', source '<type>/<name>' (postgres|storage|redis|mysql|mongodb), sourceName = canonical key; the internal model behind the cloud's secret_bindings (openapi.yaml:541-587, 6425-6607). Routes for it are NOT in WP5.
// dbUrl, bucket, s3, storagePublic: DEPRECATED, migrated into databases/buckets by state.migrateState, never read afterwards.

// Adapters
export interface DatabaseAdapter {
  provision(ref: string, network: string, name: string): Promise<{ url: string; container: string }>
  query(container: string, sql: string): Promise<string>
  cloneInto(srcContainer: string, dstContainer: string): Promise<void>
  destroy(container: string): Promise<void>
}
export interface StorageAdapter {
  provision(ref: string, network: string, name: string): Promise<{ bucket: string; env: Record<string, string> }>
  cloneInto(srcBucket: string, dstBucket: string, network: string): Promise<void>
  destroy(bucket: string, network: string): Promise<void>
  setAccess?(bucket: string, network: string, isPublic: boolean): Promise<void>
  // object ops unchanged (they already take the env bundle)
}
// ComputeAdapter.deploy opts unchanged for WP5 (alwaysOn is a scheduler concern read from Project.computeServices, not passed to docker)

// Template deployment record (state.templateDeployments[id])
export interface TemplateDeploymentRecord {
  id: string; projectId: string; branchId: string
  templateCode: string; templateVersion: string; templateSource: string   // maintainer ?? 'official'
  status: 'running' | 'succeeded' | 'failed' | 'partial'
  step: 'create_services' | 'write_variables' | 'deploy' | 'health_check'
  services: Record<string, {           // keyed by MANIFEST key; serviceName = minted platform name
    serviceName: string; serviceId?: string; type: 'web' | 'postgres'
    image?: string; port?: number; healthcheck?: string; volumeGib?: number; alwaysOn?: boolean
    env: Record<string, { source: 'fixed' | 'generated' | 'platform' | 'required' | 'optional'; generator?: string; value?: string; ref?: string }>
    url?: string; state: 'pending' | 'created' | 'deployed' | 'healthy' | 'failed'
  }>
  manifestDigest: string; digestEpoch: 2; claimToken: string
  error?: string; logsTail?: string
  createdAt: string; updatedAt: string   // ISO
}

// src/state.ts
export interface State { ...; templateDeployments: Record<string, TemplateDeploymentRecord> }
EMPTY gains templateDeployments: {}; loadState() applies migrateState() (idempotent, pure over the JSON).

GATED_ACTIONS unchanged (types.ts:7): template deploy gates service.add + secrets.write + deploy; the cloud's extra service.upgrade gate for volume-bearing manifests (templates.ts:443) has no oss action and is dropped (documented in COMPATIBILITY.md).
